 // 逗号分隔\n  alert_threshold    Int       @default(3) @db.SmallInt // 连续失败 N 次告警\n  fail_count         Int       @default(0) @db.SmallInt // 连续失败计数\n  dependency_job_ids Json?     @map(\"dependency_job_ids\") // 依赖的前置任务 ID 数组\n  dependency_mode    String?   @default(\"all\") @db.VarChar(8) // all / any\n  on_dependency_fail String?   @default(\"skip\") @db.VarChar(16) // skip / abort\n  run_after_success  Boolean   @default(true) @map(\"run_after_success\")\n\n  @@index([tenant_id])\n  @@map(\"sys_job\")\n}\n\nmodel sys_job_log {\n  log_id         String   @id @default(uuid()) @db.Uuid\n  job_id         String   @db.Uuid\n  job_name       String   @db.VarChar(128)\n  invoke_target  String   @db.VarChar(256)\n  job_message    String?  @db.VarChar(512)\n  status         String   @default(\"1\") @db.VarChar(10)\n  exception_info String?  @db.Text\n  created_at     DateTime @default(now()) @db.Timestamptz(6)\n  retry_attempt  Int      @default(0) @db.SmallInt\n  duration_ms    Int      @default(0) @db.Integer /// 执行时长（毫秒）\n  created_by     String?  @db.Uuid /// 创建人ID\n\n  @@index([job_id])\n  @@index([created_at])\n  @@map(\"sys_job_log\")\n}\n\nmodel sys_job_run {\n  run_id         String    @id @default(uuid()) @db.Uuid\n  tenant_id      String    @db.Uuid\n  job_id         String    @db.Uuid\n  triggered_by   String    @db.VarChar(32) // cron / manual / dependency / retry\n  trigger_parent String?   @db.Uuid // 上游 run_id\n  status         String    @db.VarChar(16) // running / success / failed / skipped\n  started_at     DateTime  @default(now()) @db.Timestamptz()\n  finished_at    DateTime? @db.Timestamptz()\n  duration_ms    Int?\n  error_msg      String?\n\n  @@index([job_id, started_at(sort: Desc)])\n  @@index([status])\n  @@map(\"sys_job_run\")\n}\n\nmodel sys_todo {\n  todo_id    String    @id @default(uuid()) @db.Uuid\n  tenant_id  String    @db.Uuid\n  user_id    String    @db.Uuid\n  title      String    @db.VarChar(256)\n  content    String?   @db.Text\n  priority   Int       @default(0) @db.SmallInt\n  due_time   DateTime? @db.Timestamptz(6)\n  created_by String?   @db.Uuid\n  updated_by String?   @db.Uuid\n  status     String    @default(\"0\") @db.VarChar(10)\n  created_at DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at DateTime  @updatedAt @db.Timestamptz(6)\n  is_deleted Int       @default(0) @db.SmallInt\n  group_id   String?   @db.Uuid\n  remind_at  DateTime? @db.Timestamptz(6)\n  reminded   Int       @default(0) @db.SmallInt // 是否已提醒\n  tags       String?   @db.VarChar(256) // 逗号分隔\n\n  @@index([tenant_id, user_id])\n  @@index([status])\n  @@map(\"sys_todo\")\n}\n\nmodel sys_ip_rule {\n  rule_id    String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  rule_type  String   @db.VarChar(10)\n  ip_pattern String   @db.VarChar(64)\n  remark     String?  @db.VarChar(256)\n  status     String   @default(\"1\") @db.VarChar(10)\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n  updated_at DateTime @updatedAt @db.Timestamptz(6)\n  created_by String?  @db.Uuid\n  updated_by String?  @db.Uuid\n  is_deleted Int      @default(0) @db.SmallInt\n\n  @@index([tenant_id, rule_type])\n  @@map(\"sys_ip_rule\")\n}\n\n/// 通知渠道配置（每租户一份）\nmodel sys_notice_channel {\n  channel_id   String   @id @default(uuid()) @db.Uuid\n  tenant_id    String   @db.Uuid\n  channel_type String   @db.VarChar(32) /// email | sms | webhook | wechat_work | dingtalk\n  enabled      Int      @default(0) @db.SmallInt\n  config       String?  @db.Text /// JSON 配置（SMTP/SMS 签名/Webhook URL 等）\n  remark       String?  @db.VarChar(256)\n  created_at   DateTime @default(now()) @db.Timestamptz(6)\n  updated_at   DateTime @updatedAt @db.Timestamptz(6)\n  created_by   String?  @db.Uuid\n  updated_by   String?  @db.Uuid\n  is_deleted   Int      @default(0) @db.SmallInt\n\n  @@unique([tenant_id, channel_type])\n  @@index([tenant_id])\n  @@map(\"sys_notice_channel\")\n}\n\n/// 通知发送日志\nmodel sys_notice_send_log {\n  log_id       String   @id @default(uuid()) @db.Uuid\n  tenant_id    String   @db.Uuid\n  notice_id    String?  @db.Uuid\n  channel_type String   @db.VarChar(32)\n  receiver     String   @db.VarChar(256) /// 邮箱/手机号/URL\n  status       String   @default(\"1\") @db.VarChar(10)\n  error_msg    String?  @db.Text\n  created_at   DateTime @default(now()) @db.Timestamptz(6) /// 创建时间\n  created_by   String?  @db.Uuid /// 创建人ID\n\n  @@index([tenant_id, channel_type])\n  @@index([notice_id])\n  @@index([created_at])\n  @@map(\"sys_notice_send_log\")\n}\n\nmodel sys_password_history {\n  id         String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  user_id    String   @db.Uuid\n  password   String   @db.VarChar(256)\n  created_at DateTime @default(now()) @db.Timestamptz(6) /// 创建时间\n  created_by String?  @db.Uuid /// 创建人ID\n\n  @@index([tenant_id, user_id, created_at])\n  @@map(\"sys_password_history\")\n}\n\nmodel sys_todo_group {\n  group_id   String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  user_id    String   @db.Uuid\n  name       String   @db.VarChar(64)\n  color      String?  @db.VarChar(16)\n  sort_order Int      @default(0)\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n  updated_at DateTime @updatedAt @db.Timestamptz(6)\n  is_deleted Int      @default(0) @db.SmallInt\n  created_by String?  @db.Uuid\n  updated_by String?  @db.Uuid\n\n  @@index([tenant_id, user_id])\n  @@map(\"sys_todo_group\")\n}\n\nmodel sys_user_tenant {\n  id         String   @id @default(uuid()) @db.Uuid\n  user_id    String   @db.Uuid\n  tenant_id  String   @db.Uuid\n  is_default Int      @default(0) @db.SmallInt\n  joined_at  DateTime @default(now()) @db.Timestamptz(6) /// 加入时间\n  created_by String?  @db.Uuid /// 创建人ID\n\n  @@unique([user_id, tenant_id])\n  @@index([user_id])\n  @@index([tenant_id])\n  @@map(\"sys_user_tenant\")\n}\n\nmodel gen_table {\n  table_id        String   @id @default(uuid()) @db.Uuid\n  table_name      String   @unique @db.VarChar(200)\n  table_comment   String?  @db.VarChar(500)\n  class_name      String   @db.VarChar(100)\n  tpl_category    String   @default(\"crud\") @db.VarChar(20)\n  package_name    String?  @db.VarChar(100)\n  module_name     String?  @db.VarChar(30)\n  business_name   String?  @db.VarChar(30)\n  function_name   String?  @db.VarChar(50)\n  function_author String?  @db.VarChar(50)\n  table_status    String   @default(\"pending\") @db.VarChar(20) // pending / created / altered\n  // 规范字段\n  tenant_id       String   @db.Uuid\n  created_at      DateTime @default(now())\n  updated_at      DateTime @updatedAt\n  created_by      String?  @db.Uuid\n  updated_by      String?  @db.Uuid\n  is_deleted      Int      @default(0) @db.SmallInt\n\n  // 无数据库外键，应用层维护\n  columns gen_table_column[]\n\n  @@index([tenant_id])\n  @@index([is_deleted])\n  @@map(\"gen_table\")\n}\n\nmodel gen_table_column {\n  column_id         String     @id @default(uuid()) @db.Uuid\n  table_id          String     @db.Uuid\n  column_name       String     @db.VarChar(200)\n  column_comment    String?    @db.VarChar(500)\n  column_type       String     @db.VarChar(100) // varchar(64) / int4 / uuid ...\n  ts_type           String?    @db.VarChar(50) // string / number / Date ...\n  field_name        String?    @db.VarChar(200) // camelCase\n  is_pk             String     @default(\"0\") @db.Char(1)\n  is_increment      String     @default(\"0\") @db.Char(1)\n  is_required       String     @default(\"0\") @db.Char(1)\n  is_insert         String     @default(\"1\") @db.Char(1)\n  is_edit           String     @default(\"1\") @db.Char(1)\n  is_list           String     @default(\"1\") @db.Char(1)\n  is_query          String     @default(\"0\") @db.Char(1)\n  is_sort           String     @default(\"0\") @db.Char(1) // 是否参与排序\n  query_type        String     @default(\"EQ\") @db.VarChar(20)\n  html_type         String     @default(\"input\") @db.VarChar(20)\n  dict_type         String?    @db.VarChar(200)\n  default_value     String?    @db.VarChar(200)\n  sort              Int?\n  is_deleted        Int        @default(0) @db.SmallInt\n  genTable          gen_table? @relation(fields: [gen_tableTable_id], references: [table_id])\n  gen_tableTable_id String?    @db.Uuid\n\n  @@index([table_id])\n  @@index([table_id, is_deleted])\n  @@map(\"gen_table_column\")\n}\n\nmodel sys_upload_task {\n  task_id      String   @id @default(uuid())\n  upload_id    String\n  file_name    String\n  total_chunks Int\n  status       String // pending | merging | uploading | completed | failed\n  progress     Int      @default(0) // 0 ~ 100\n  error_msg    String?\n  file_id      String?\n  url          String?\n  size         BigInt?\n  tenant_id    String?\n  user_id      String?\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  @@index([upload_id])\n  @@index([status])\n  @@map(\"sys_upload_task\")\n}\n\n/// 每日审计聚合（保留 2 年）\nmodel sys_audit_daily {\n  id          String   @id @default(uuid()) @db.Uuid\n  tenant_id   String   @db.Uuid\n  stat_date   DateTime @db.Date\n  operation   String   @db.VarChar(128)\n  total_count Int      @default(0)\n  fail_count  Int      @default(0)\n  avg_time_ms Int      @default(0)\n  p95_time_ms Int      @default(0)\n\n  @@unique([tenant_id, stat_date, operation])\n  @@index([tenant_id, stat_date])\n  @@map(\"sys_audit_daily\")\n}\n\n/// 每日登录聚合\nmodel sys_login_daily {\n  id           String   @id @default(uuid()) @db.Uuid\n  tenant_id    String   @db.Uuid\n  stat_date    DateTime @db.Date\n  total_count  Int      @default(0)\n  fail_count   Int      @default(0)\n  unique_users Int      @default(0)\n\n  @@unique([tenant_id, stat_date])\n  @@map(\"sys_login_daily\")\n}\n\n// ==================== 审批申请主表 ====================\nmodel sys_approval_request {\n  request_id      String   @id @default(uuid()) @db.Uuid\n  tenant_id       String   @db.Uuid\n  title           String   @db.VarChar(256)\n  content         String?  @db.Text\n  form_data       Json?\n  applicant_id    String   @db.Uuid\n  current_dept_id String   @db.Uuid\n  status          String   @default(\"0\") @db.VarChar(20)\n  is_deleted      Int      @default(0) @db.SmallInt\n  created_at      DateTime @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime @updatedAt @db.Timestamptz(6)\n  created_by      String?  @db.Uuid\n  updated_by      String?  @db.Uuid\n\n  // ===== 反向关系字段 =====\n  nodes sys_approval_node[]\n  logs  sys_approval_log[]\n\n  @@index([tenant_id, status])\n  @@index([tenant_id, applicant_id])\n  @@index([is_deleted])\n  @@map(\"sys_approval_request\")\n}\n\n// ==================== 审批节点表 ====================\nmodel sys_approval_node {\n  node_id            String    @id @default(uuid()) @db.Uuid\n  tenant_id          String    @db.Uuid\n  request_id         String    @db.Uuid\n  dept_id            String    @db.Uuid\n  approver_id        String?   @db.Uuid\n  sequence           Int\n  status             String    @default(\"0\") @db.VarChar(20)\n  is_current         Int       @default(0) @db.SmallInt\n  round              Int       @default(1)\n  reject_reason_type String?   @db.VarChar(64)\n  reject_reason      String?   @db.VarChar(512)\n  approved_at        DateTime? @db.Timestamptz(6)\n  is_deleted         Int       @default(0) @db.SmallInt\n  created_at         DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at         DateTime  @updatedAt @db.Timestamptz(6)\n  created_by         String?   @db.Uuid\n  updated_by         String?   @db.Uuid\n\n  // ===== 关系字段 =====\n  request sys_approval_request @relation(fields: [request_id], references: [request_id], onDelete: Cascade)\n\n  @@index([tenant_id, request_id])\n  @@index([tenant_id, dept_id, status])\n  @@map(\"sys_approval_node\")\n}\n\n// ==================== 审批操作日志表 ====================\nmodel sys_approval_log {\n  log_id        String   @id @default(uuid()) @db.Uuid\n  tenant_id     String   @db.Uuid\n  request_id    String   @db.Uuid\n  operator_id   String   @db.Uuid\n  operator_name String   @db.VarChar(64)\n  action        String   @db.VarChar(32)\n  from_status   String?  @db.VarChar(20)\n  to_status     String?  @db.VarChar(20)\n  remark        String?  @db.Text\n  reason_type   String?  @db.VarChar(64)\n  metadata      Json?\n  created_at    DateTime @default(now()) @db.Timestamptz(6)\n  created_by    String?  @db.Uuid\n\n  // ===== 关系字段 =====\n  request sys_approval_request @relation(fields: [request_id], references: [request_id], onDelete: Cascade)\n\n  @@index([tenant_id, request_id])\n  @@index([created_at])\n  @@map(\"sys_approval_log\")\n}\n\nmodel sys_notice_template {\n  template_id    String   @id @default(uuid()) @db.Uuid\n  tenant_id      String   @db.Uuid\n  template_code  String   @db.VarChar(64)\n  template_name  String   @db.VarChar(128)\n  channel_type   String   @db.VarChar(32)\n  title          String?  @db.VarChar(256)\n  content        String   @db.Text\n  content_format String   @default(\"markdown\") @db.VarChar(16)\n  remark         String?  @db.VarChar(512)\n  params         Json?\n  status         String   @default(\"1\")\n  created_at     DateTime @default(now())\n  updated_at     DateTime @updatedAt\n  created_by     String?  @db.Uuid\n  updated_by     String?  @db.Uuid\n  is_deleted     Int      @default(0) @db.SmallInt\n\n  @@unique([tenant_id, template_code])\n  @@map(\"sys_notice_template\")\n}\n\nmodel sys_file_pending_delete {\n  id          String   @id @default(uuid()) @db.Uuid\n  tenant_id   String   @db.Uuid\n  url         String\n  retry_count Int      @default(0)\n  next_retry  DateTime @default(now())\n  last_error  String?\n  created_at  DateTime @default(now())\n\n  @@index([next_retry])\n}\n\n/// ==================== 流程定义 ====================\nmodel wf_definition {\n  def_id         String   @id @default(uuid()) @db.Uuid\n  tenant_id      String   @db.Uuid\n  def_key        String   @db.VarChar(64) /// 流程唯一标识\n  def_name       String   @db.VarChar(128)\n  version        Int      @default(1) /// 版本号\n  category       String?  @db.VarChar(64) /// 分类\n  description    String?  @db.VarChar(512)\n  definition     Json /// BPMN JSON 定义\n  definition_xml String?  @db.Text /// BPMN XML 原文（画布还原用）\n  /**\n   * 表单配置 [{ field, label, type, required }]\n   */\n  form_schema    Json?\n  /**\n   * 变量定义 [{ name, type, defaultValue }]\n   */\n  var_schema     Json?\n  status         String   @default(\"1\") @db.VarChar(10) /// 0-草稿 1-已发布 2-已停用\n  created_at     DateTime @default(now()) @db.Timestamptz(6)\n  updated_at     DateTime @updatedAt @db.Timestamptz(6)\n  created_by     String?  @db.Uuid\n  updated_by     String?  @db.Uuid\n  is_deleted     Int      @default(0) @db.SmallInt\n\n  instances wf_instance[]\n\n  @@unique([tenant_id, def_key, version])\n  @@index([tenant_id, status])\n  @@index([is_deleted])\n  @@map(\"wf_definition\")\n}\n\n/// ==================== 流程实例 ====================\nmodel wf_instance {\n  instance_id         String            @id @default(uuid()) @db.Uuid\n  tenant_id           String            @db.Uuid\n  def_id              String            @db.Uuid\n  def_key             String            @db.VarChar(64)\n  def_version         Int\n  business_key        String?           @db.VarChar(128) /// 业务单号\n  title               String            @db.VarChar(256)\n  initiator_id        String            @db.Uuid /// 发起人\n  initiator_dept_id   String?           @db.Uuid /// 发起人部门\n  variables           Json /// 流程变量快照\n  /**\n   * 当前活跃节点列表（支持并行）\n   */\n  active_nodes        Json              @default(\"[]\")\n  status              String            @default(\"0\") @db.VarChar(20)\n  /**\n   * 0-运行中 1-已完成 2-已终止 3-已挂起\n   */\n  start_at            DateTime          @default(now()) @db.Timestamptz(6)\n  end_at              DateTime?         @db.Timestamptz(6)\n  duration_ms         Int? /// 总耗时\n  parent_instance_id  String?           @db.Uuid /// 子流程场景\n  created_at          DateTime          @default(now()) @db.Timestamptz(6)\n  updated_at          DateTime          @updatedAt @db.Timestamptz(6)\n  is_deleted          Int               @default(0) @db.SmallInt\n  priority            Int?              @default(0) /// 优先级\n  def                 wf_definition     @relation(fields: [def_id], references: [def_id])\n  tasks               wf_task[]\n  variables_log       wf_variable_log[]\n  history             wf_history[]\n  /// 超时通知时间（避免重复通知）\n  timeout_notified_at DateTime?         @db.Timestamptz(6)\n  /// 最后超时扫描时间\n  last_scanned_at     DateTime?         @db.Timestamptz(6)\n\n  @@index([tenant_id, status])\n  @@index([tenant_id, initiator_id])\n  @@index([tenant_id, business_key])\n  @@index([parent_instance_id])\n  @@index([tenant_id, def_key, status])\n  @@index([tenant_id, start_at(sort: Desc)])\n  @@map(\"wf_instance\")\n}\n\n/// ==================== 任务 ====================\nmodel wf_task {\n  task_id       String      @id @default(uuid()) @db.Uuid\n  tenant_id     String      @db.Uuid\n  instance_id   String      @db.Uuid\n  node_id       String      @db.VarChar(64) /// 节点 ID\n  node_name     String      @db.VarChar(128)\n  node_type     String      @db.VarChar(32) /// userTask | countersign | orSign\n  assignee_id   String?     @db.Uuid /// 审批人\n  assignee_type String      @db.VarChar(32) /// user | role | dept | initiator\n  candidate_ids Json? /// 候选用户列表（多签场景）\n  sign_type     String?     @db.VarChar(20) /// all-会签 any-或签 sequential-顺序\n  sign_strategy Json? /// { percent: 60 } 比例通过\n  completed_ids Json?       @default(\"[]\") /// 已签署用户\n  status        String      @default(\"0\") @db.VarChar(20)\n  /// 0-待处理 1-已完成 2-已取消 3-已超时\n  action        String?     @db.VarChar(32) /// approve | reject | ...\n  comment       String?     @db.Text\n  /**\n   * 表单提交数据\n   */\n  form_data     Json?\n  due_at        DateTime?   @db.Timestamptz(6)\n  claimed_at    DateTime?   @db.Timestamptz(6)\n  completed_at  DateTime?   @db.Timestamptz(6)\n  duration_ms   Int?\n  created_at    DateTime    @default(now()) @db.Timestamptz(6)\n  updated_at    DateTime    @updatedAt @db.Timestamptz(6)\n  is_deleted    Int         @default(0) @db.SmallInt\n  priority      Int?        @default(0) /// 优先级\n  instance      wf_instance @relation(fields: [instance_id], references: [instance_id])\n\n  @@index([tenant_id, assignee_id, status])\n  @@index([tenant_id, instance_id])\n  @@index([tenant_id, node_id, status])\n  @@index([tenant_id, due_at])\n  @@index([due_at])\n  @@index([tenant_id, assignee_id, status, priority])\n  @@map(\"wf_task\")\n}\n\n/// ==================== 流程历史 ====================\nmodel wf_history {\n  history_id    String   @id @default(uuid()) @db.Uuid\n  tenant_id     String   @db.Uuid\n  instance_id   String   @db.Uuid\n  node_id       String   @db.VarChar(64)\n  node_name     String   @db.VarChar(128)\n  node_type     String   @db.VarChar(32)\n  event_type    String   @db.VarChar(32)\n  /// start | complete | reject | terminate | assign | unassign\n  operator_id   String?  @db.Uuid\n  operator_name String?  @db.VarChar(64)\n  comment       String?  @db.Text\n  variables     Json?\n  duration_ms   Int?\n  created_at    DateTime @default(now()) @db.Timestamptz(6)\n\n  instance wf_instance @relation(fields: [instance_id], references: [instance_id])\n\n  @@index([tenant_id, instance_id])\n  @@index([created_at])\n  @@map(\"wf_history\")\n}\n\n/// ==================== 变量历史 ====================\nmodel wf_variable_log {\n  log_id              String      @id @default(uuid()) @db.Uuid\n  tenant_id           String      @db.Uuid\n  instance_id         String      @db.Uuid\n  task_id             String?     @db.Uuid\n  key                 String      @db.VarChar(64)\n  value               Json?\n  created_at          DateTime    @default(now()) @db.Timestamptz(6)\n  created_by          String?     @db.Uuid\n  timeout_notified_at DateTime?   @db.Timestamptz(6)\n  last_scanned_at     DateTime?   @db.Timestamptz(6)\n  instance            wf_instance @relation(fields: [instance_id], references: [instance_id])\n\n  @@index([tenant_id, instance_id])\n  @@map(\"wf_variable_log\")\n}\n\n/// ==================== 数据集 ====================\nmodel rp_dataset {\n  dataset_id    String   @id @default(uuid()) @db.Uuid\n  tenant_id     String   @db.Uuid\n  dataset_code  String   @db.VarChar(64)\n  dataset_name  String   @db.VarChar(128)\n  description   String?  @db.VarChar(512)\n  category      String?  @db.VarChar(64)\n  /**\n   * 数据集类型：sql | api | json\n   */\n  dataset_type  String   @default(\"sql\") @db.VarChar(20)\n  /**\n   * SQL 数据源配置：{ sql, timeout, maxRows }\n   */\n  source_config Json\n  /**\n   * 参数定义 [{ name, type, required, defaultValue }]\n   */\n  params        Json?\n  /**\n   * 字段元信息 [{ name, type, label }]\n   */\n  fields        Json?\n  status        String   @default(\"1\") @db.VarChar(10)\n  created_at    DateTime @default(now()) @db.Timestamptz(6)\n  updated_at    DateTime @updatedAt @db.Timestamptz(6)\n  created_by    String?  @db.Uuid\n  updated_by    String?  @db.Uuid\n  is_deleted    Int      @default(0) @db.SmallInt\n\n  reports rp_report[]\n\n  @@unique([tenant_id, dataset_code])\n  @@index([tenant_id, category])\n  @@map(\"rp_dataset\")\n}\n\n/// ==================== 报表 ====================\nmodel rp_report {\n  report_id     String   @id @default(uuid()) @db.Uuid\n  tenant_id     String   @db.Uuid\n  report_code   String   @db.VarChar(64)\n  report_name   String   @db.VarChar(128)\n  description   String?  @db.VarChar(512)\n  category      String?  @db.VarChar(64)\n  dataset_id    String   @db.Uuid\n  /**\n   * 报表配置：{ chartType, columns, layout, colors }\n   */\n  config        Json?\n  /**\n   * 报表参数（覆盖数据集参数）\n   */\n  params        Json?\n  /**\n   * 权限控制：允许访问的角色列表\n   */\n  allowed_roles Json?\n  status        String   @default(\"1\") @db.VarChar(10)\n  created_at    DateTime @default(now()) @db.Timestamptz(6)\n  updated_at    DateTime @updatedAt @db.Timestamptz(6)\n  created_by    String?  @db.Uuid\n  updated_by    String?  @db.Uuid\n  is_deleted    Int      @default(0) @db.SmallInt\n\n  dataset rp_dataset      @relation(fields: [dataset_id], references: [dataset_id])\n  logs    rp_report_log[]\n\n  @@unique([tenant_id, report_code])\n  @@index([tenant_id, category])\n  @@map(\"rp_report\")\n}\n\n/// ==================== 报表执行日志 ====================\nmodel rp_report_log {\n  log_id      String   @id @default(uuid()) @db.Uuid\n  tenant_id   String   @db.Uuid\n  report_id   String   @db.Uuid\n  report_code String   @db.VarChar(64)\n  params      Json?\n  row_count   Int      @default(0)\n  duration_ms Int      @default(0)\n  /**\n   * 1-成功 0-失败\n   */\n  status      String   @default(\"1\") @db.VarChar(10)\n  error_msg   String?  @db.Text\n  export_type String?  @db.VarChar(20) /// excel | pdf | html\n  created_at  DateTime @default(now()) @db.Timestamptz(6)\n  created_by  String?  @db.Uuid\n\n  report rp_report @relation(fields: [report_id], references: [report_id])\n\n  @@index([tenant_id, report_id])\n  @@index([created_at])\n  @@index([tenant_id, export_type, created_at(sort: Desc)])\n  @@map(\"rp_report_log\")\n}\n\n/// ==================== 报表收藏 ====================\nmodel rp_report_favorite {\n  id         String   @id @default(uuid()) @db.Uuid\n  tenant_id  String   @db.Uuid\n  user_id    String   @db.Uuid\n  report_id  String   @db.Uuid\n  created_at DateTime @default(now()) @db.Timestamptz(6)\n\n  @@unique([user_id, report_id])\n  @@index([tenant_id, user_id])\n  @@map(\"rp_report_favorite\")\n}\n\n/// ==================== 报表异步导出任务 ====================\nmodel rp_export_task {\n  task_id       String    @id @default(uuid()) @db.Uuid\n  tenant_id     String    @db.Uuid\n  user_id       String    @db.Uuid\n  report_code   String    @db.VarChar(64)\n  export_type   String    @db.VarChar(20) /// excel | pdf | html | csv\n  params        Json?\n  /// pending | processing | completed | failed | cancelled\n  status        String    @default(\"pending\") @db.VarChar(20)\n  /// 进度 0-100\n  progress      Int       @default(0) @db.SmallInt\n  row_count     Int       @default(0)\n  /// 文件信息\n  file_url      String?   @db.VarChar(512)\n  file_name     String?   @db.VarChar(256)\n  file_size     BigInt?\n  /// 失败信息\n  error_msg     String?   @db.Text\n  /// 重试计数\n  retry_count   Int       @default(0) @db.SmallInt\n  duration_ms   Int?\n  /// BullMQ Job ID（用于取消/查询）\n  job_id        String?   @db.VarChar(64)\n  created_at    DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at    DateTime  @updatedAt @db.Timestamptz(6)\n  started_at    DateTime? @db.Timestamptz(6)\n  completed_at  DateTime? @db.Timestamptz(6)\n  expires_at    DateTime? @db.Timestamptz(6) /// 文件过期时间\n  max_retries   Int       @default(3) @db.SmallInt\n  /**\n   * 下次重试时间\n   */\n  next_retry_at DateTime? @db.Timestamptz(6)\n  /**\n   * 最后一次错误类型\n   */\n  error_type    String?   @db.VarChar(20)\n  /**\n   * 完整错误堆栈（截断）\n   */\n  error_stack   String?   @db.Text\n\n  @@index([tenant_id, user_id, status, created_at(sort: Desc)])\n  @@index([status, created_at])\n  @@index([expires_at])\n  @@index([status, next_retry_at])\n  @@map(\"rp_export_task\")\n}\n\n/// ==================== 工作流通知日志 ====================\nmodel wf_notification {\n  notification_id String    @id @default(uuid()) @db.Uuid\n  tenant_id       String    @db.Uuid\n  instance_id     String    @db.Uuid\n  task_id         String?   @db.Uuid\n  node_id         String?   @db.VarChar(64)\n  /// assign | complete | reject | timeout | terminate | cc | start\n  event_type      String    @db.VarChar(32)\n  /// email | sms | webhook | in_app | wechat_work | dingtalk\n  channel_type    String    @db.VarChar(32)\n  receiver_id     String?   @db.Uuid\n  receiver_addr   String?   @db.VarChar(256)\n  template_code   String?   @db.VarChar(64)\n  title           String?   @db.VarChar(256)\n  content         String?   @db.Text\n  /// 0-待发送 1-已发送 2-发送失败 3-已跳过\n  status          String    @default(\"0\") @db.VarChar(10)\n  error_msg       String?   @db.Text\n  retry_count     Int       @default(0) @db.SmallInt\n  sent_at         DateTime? @db.Timestamptz(6)\n  created_at      DateTime  @default(now()) @db.Timestamptz(6)\n\n  @@index([tenant_id, instance_id])\n  @@index([tenant_id, task_id])\n  @@index([status, created_at])\n  @@index([event_type, created_at])\n  @@map(\"wf_notification\")\n}\n\n/// ==================== 报表预热配置 ====================\nmodel rp_cache_warm_config {\n  config_id       String    @id @default(uuid()) @db.Uuid\n  tenant_id       String    @db.Uuid\n  report_code     String    @db.VarChar(64)\n  /**\n   * 预热参数 JSON\n   */\n  warm_params     Json?\n  /**\n   * 预热频率：cron 表达式\n   */\n  cron_expression String    @default(\"0 */30 * * * ?\") @db.VarChar(64)\n  /**\n   * 是否启用\n   */\n  enabled         Int       @default(1) @db.SmallInt\n  /**\n   * 缓存 TTL（秒）\n   */\n  cache_ttl       Int       @default(1800)\n  /**\n   * 最后预热时间\n   */\n  last_warm_at    DateTime? @db.Timestamptz(6)\n  /**\n   * 最后预热状态 1-成功 0-失败\n   */\n  last_status     String?   @db.VarChar(10)\n  /**\n   * 最后错误信息\n   */\n  last_error      String?   @db.Text\n  remark          String?   @db.VarChar(512)\n  created_at      DateTime  @default(now()) @db.Timestamptz(6)\n  updated_at      DateTime  @updatedAt @db.Timestamptz(6)\n  created_by      String?   @db.Uuid\n  updated_by      String?   @db.Uuid\n  is_deleted      Int       @default(0) @db.SmallInt\n\n  @@unique([tenant_id, report_code])\n  @@index([tenant_id, enabled])\n  @@index([last_warm_at])\n  @@map(\"rp_cache_warm_config\")\n}\n",
